\label{lem: NEChara}
  Consider an arbitrary strategy profile $x^* = (y^*,z^*)$.
  Then, $x^*$ is an NE if and only if  $y^*$ solves \eqref{eq: LCP}
  and \eqref{eq: IntOpt} simultaneously.

\label{lem: RationalSol}
  Consider an arbitrary strategy profile $x^* = (y^*,z^*)$. If
  the system of (in-)equalities given by~\eqref{eq: LCP}
  and~\eqref{eq: IntOpt} admits a solution, it admits a rational one
  as well.

\label{claim: SSetIntOpt}
    The set of solutions of \eqref{eq: IntOpt} is a union of
    rational polyhedra.

\label{thm:pos}
  If $G$ admits a Nash equilibrium, it also admits a rational Nash
  equilibrium.

\label{claim: BR}
  The best response map of player $1$ and $2$ fulfill
  $\mathrm{BR}_1(x_2,y_3,0) = \mathrm{BR}_2(x_1,y_3,0) = \mathrm{BR}(y_3,0)$ for
  all $x_1,x_2,y_3$ with
  \begin{align*}
    \mathrm{BR}(y_3,0)=
    \begin{cases}
      (\nicefrac{y_3}{2},1),
      &\text{ if } y_3 \in\mathbb{R}\setminus
      \left[2-2\sqrt{2},2+2\sqrt{2}\right]
      \\
      \{(\nicefrac{y_3}{2},1)\}\cup\{(0,0)\},
      &\text{ if } y_3 \in \{ 2-2\sqrt{2},2+2\sqrt{2} \}
      \\
      (0,0),
      &\text{ if } y_3 \in
      \left]2-2\sqrt{2},2+2\sqrt{2}\right[.
    \end{cases}
  \end{align*}

By \Cref{lem: 1Piecewise}, we know that for any $i\in
  \{1,\ldots,k\}$, the set of solutions of $f_i(x)\leq 0$ is the union
  of rational polyhedra. Let us denote these polyhedra via $P_l^i$ with $l\in \{1,\ldots,L_i\}$
  and $L_i\in \mathbb{N}$.
  Hence, the set of solutions of the entire system is given by
  \begin{align*}
    \bigcap_{i=1}^k\bigcup_{l=1}^{L_i} P_l^i
    = \bigcup_{(l_i)_{i}\in \prod_{i=1}^k\{1,\ldots,L_i\}}
    \bigcap_{i=1}^k P^i_{l_i}
  \end{align*}
  and since $\bigcap_{i=1}^kP^i_{l_i}$ is a rational
  polyhedron (as it is the intersection of rational polyhedra),
  the proof is complete.

\label{lemma:opt-val-func-of-lp}
  Consider the optimal-value function function
  \begin{equation*}
    \varphi(c) \mathrel{{\mathop:}{=}} \min \left\{c^\top x\defsepA x \leq b\right\}
  \end{equation*}
  of a linear optimization problem with rational constraint data~$A
  \in \mathbb{Q}^{m \times n}$ and $b \in \mathbb{Q}^{m}$.
  Then, $\varphi$ is a piecewise linear function with rational parameters.
